import AppKit
import Foundation

@MainActor
final class PasteboardMonitor: ObservableObject {
    @Published var pins: [PinnedClipItem] = []
    @Published var pairingUri: String = ""
    @Published var statusMessage: String = "Syncing via E2EE relay"
    @Published var launchAtLogin: Bool = false

    private let core: CoreBridge
    private var timer: DispatchSourceTimer?
    private var lastChangeCount: Int

    private let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    init(core: CoreBridge) {
        self.core = core
        self.lastChangeCount = NSPasteboard.general.changeCount
        self.pairingUri = core.getPairingUri()
        self.pins = core.getPins()
        self.launchAtLogin = LaunchAtLogin.ensureDefaultEnabled()
        startPolling()
    }

    func setLaunchAtLogin(_ enabled: Bool) {
        let actual = LaunchAtLogin.setEnabled(enabled)
        launchAtLogin = actual
        if enabled && !actual {
            statusMessage = "Move ClipSync.app to /Applications for login item"
        } else {
            statusMessage = actual ? "Start at Login enabled" : "Start at Login disabled"
        }
    }

    func stop() {
        timer?.cancel()
        timer = nil
    }

    private func startPolling() {
        let src = DispatchSource.makeTimerSource(queue: .main)
        // 500ms interval with 200ms leeway allows macOS App Nap coalescing for near-zero idle energy.
        src.schedule(deadline: .now() + .milliseconds(500), repeating: .milliseconds(500), leeway: .milliseconds(200))
        src.setEventHandler { [weak self] in
            Task { @MainActor [weak self] in
                self?.tick()
            }
        }
        src.resume()
        self.timer = src
    }

    private func tick() {
        drainRemoteClips()
        checkLocalPasteboard()
        let latestPins = core.getPins()
        if latestPins.map(\.idKey) != pins.map(\.idKey) || latestPins.map(\.updatedAtMs) != pins.map(\.updatedAtMs) {
            pins = latestPins
        }
    }

    private func drainRemoteClips() {
        while let clip = core.popRemote() {
            writeToPasteboard(kind: clip.kind, data: clip.data, mime: clip.mime)
        }
    }

    private func checkLocalPasteboard() {
        let pb = NSPasteboard.general
        let currentCount = pb.changeCount
        guard currentCount != lastChangeCount else { return }
        lastChangeCount = currentCount

        if let types = pb.types, types.contains(where: { concealedTypes.contains($0.rawValue) }) {
            return
        }

        if let (kind, data) = readPasteboard(pb) {
            _ = core.pushLocal(kind: kind, data: data)
        }
    }

    private func readPasteboard(_ pb: NSPasteboard) -> (ClipSyncKind, Data)? {
        if let pngData = pb.data(forType: .png), !pngData.isEmpty {
            return (.image, pngData)
        }
        if let tiffData = pb.data(forType: .tiff),
           let rep = NSBitmapImageRep(data: tiffData),
           let pngData = rep.representation(using: .png, properties: [:]) {
            return (.image, pngData)
        }
        if let str = pb.string(forType: .string), !str.isEmpty,
           let utf8 = str.data(using: .utf8) {
            return (.text, utf8)
        }
        return nil
    }

    func pinCurrentClipboard() {
        let pb = NSPasteboard.general
        if let types = pb.types, types.contains(where: { concealedTypes.contains($0.rawValue) }) {
            statusMessage = "Skipped concealed password manager item"
            return
        }
        guard let (kind, data) = readPasteboard(pb) else {
            statusMessage = "Clipboard is empty or unsupported"
            return
        }
        if core.pinItem(kind: kind, data: data) != nil {
            pins = core.getPins()
            statusMessage = "Pinned current clipboard"
        } else {
            statusMessage = "Failed to pin clipboard item"
        }
    }

    func copyPinToClipboard(_ pin: PinnedClipItem) {
        writeToPasteboard(kind: pin.kind, data: pin.data, mime: pin.mime)
        statusMessage = "Loaded pin into clipboard"
    }

    func unpin(_ pin: PinnedClipItem) {
        if core.unpinItem(id: pin.id) {
            pins = core.getPins()
            statusMessage = "Unpinned item"
        }
    }

    func copyPairingUri() {
        guard let utf8 = pairingUri.data(using: .utf8) else { return }
        writeToPasteboard(kind: .text, data: utf8, mime: "text/plain")
        statusMessage = "Pairing URI copied"
    }

    @discardableResult
    func joinCluster(uri: String) -> Bool {
        let trimmed = uri.trimmingCharacters(in: .whitespacesAndNewlines)
        guard core.joinPairingUri(trimmed) else {
            statusMessage = "Invalid clipsync://pair URI"
            return false
        }
        pairingUri = core.getPairingUri()
        pins = core.getPins()
        statusMessage = "Joined cluster"
        return true
    }

    private func writeToPasteboard(kind: ClipSyncKind, data: Data, mime: String) {
        let pb = NSPasteboard.general
        core.recordEcho(kind: kind, data: data)

        pb.clearContents()
        switch kind {
        case .text:
            if let str = String(data: data, encoding: .utf8) {
                pb.setString(str, forType: .string)
            }
        case .image:
            let pngData: Data
            if mime == "image/png" {
                pngData = data
            } else if let nsImg = NSImage(data: data),
                      let tiff = nsImg.tiffRepresentation,
                      let rep = NSBitmapImageRep(data: tiff),
                      let converted = rep.representation(using: .png, properties: [:]) {
                pngData = converted
            } else {
                pngData = data
            }
            core.recordEcho(kind: .image, data: pngData)
            pb.setData(pngData, forType: .png)
        }
        lastChangeCount = pb.changeCount
    }
}
